reduction <- function(x,M,curve1,curve2) {
err1 <- numeric(); err2 <- numeric()
for (t in 1:72) {
m <- as.numeric(M[t,x+1])
fit1 <- MC(x=x,m=m,curve=curve1)
err1[t] <- deviance(fit1)
fit2 <- MortalityLaw(x=x,mx=m,law=curve2)
err2[t] <- sum((log(m)-log(fitted(fit2)))^2)
}
mean((err2-err1)/err2)
}
