## ----fig1,fig.cap="Fitted mortality curves (Rogers-Planck) from different methods for Australian female death rates in 2020. (Crosses are actual observations.)",echo=FALSE,results='hide',out.width="80%",warning=FALSE,message=FALSE----
M <- AUSF
x <- 0:100
t <- 71
m <- as.numeric(M[t,x+1])
fit1 <- MC(x=x,m=m,curve="rogersplanck")
fit2 <- MC(x=x,m=m,curve="rogersplanck2")
fit3 <- MortalityLaw(x=x,mx=m,law="rogersplanck")
df <- data.frame(age=x,'demofit (unconstrained)'=log(fitted(fit1)),'demofit (constrained)'=log(fitted(fit2)),'MortalityLaws'=log(fitted(fit3)),check.names=FALSE)
df_long <- df%>%pivot_longer(-age,names_to="method",values_to="logm")
df_long$method <- factor(df_long$method,levels=c("demofit (unconstrained)","demofit (constrained)","MortalityLaws"))
df_obs <- data.frame(age=x,logm=log(m))
ggplot(df_long,aes(x=age,y=logm,color=method,linetype=method)) +
geom_line(size=1) +
geom_point(data=df_obs,aes(x=age,y=logm),inherit.aes=FALSE,color="black",size=1,shape=4,stroke=1) +
scale_linetype_manual(values=c("demofit (unconstrained)"="solid","demofit (constrained)"="dashed","MortalityLaws"="dotted")) +
scale_color_manual(values=c("demofit (unconstrained)"="black","demofit (constrained)"="black","MortalityLaws"="black")) +
labs(x="age",y="log death rate",colour=NULL,linetype=NULL) +
theme_bw(base_size = 12) +
theme(axis.text=element_text(size=12),legend.text=element_text(size=12),panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),panel.border=element_blank(),axis.line=element_line(color="black"),legend.position="bottom")


## ----fig2,fig.cap="Fitted and extrapolated mortality curves (Thatcher, Weibull, Gompertz) for Swedish female death rates in 1991-2010. (Dots are actual observations.)",echo=FALSE,results='hide',out.width="80%",warning=FALSE,message=FALSE----
mf <- c(0.02292700,0.02582791,0.02947348,0.03354738,0.03830591,0.04305469,0.04951631,0.05585749,0.06330641,0.07185780,
0.08098535,0.09078352,0.10047143,0.11166913,0.12366918,0.13547566,0.14690577,0.16106022,0.17365013,0.18882075,
0.20285020,0.22113929,0.23029289,0.23223465,0.24823081,0.25638407)
x <- 80:105
fit1f <- MC(x=x,m=mf,curve="thatcher2")
fit2f <- MC(x=x,m=mf,curve="weibull2")
fit3f <- MC(x=x,m=mf,curve="gompertz2")
df1 <- data.frame(age=x,'Thatcher'=log(fitted(fit1f)),'Weibull'=log(fitted(fit2f)),'Gompertz'=log(fitted(fit3f)),Part="Fit",check.names=FALSE)
df2 <- data.frame(age=c(106:120),'Thatcher'=log(predict(fit1f,c(106:120))),'Weibull'=log(predict(fit2f,c(106:120))),'Gompertz'=log(predict(fit3f,c(106:120))),Part="Extrapolation",check.names=FALSE)
df <- rbind(df1,df2)
df_long <- df%>%pivot_longer(cols=c(Thatcher,Weibull,Gompertz),names_to="method",values_to="logm")
df_long$method <- factor(df_long$method,levels=c("Thatcher","Weibull","Gompertz"))
df_obs <- data.frame(age=x,logm=log(mf))
ggplot(df_long,aes(x=age,y=logm,color=method,linetype=interaction(method,Part))) +
geom_line(size=1) +
geom_point(data=df_obs,aes(x=age,y=logm),inherit.aes=FALSE,color="black",size=2.5) +
scale_linetype_manual(values=c("Thatcher.Fit"="solid","Weibull.Fit"="dashed","Gompertz.Fit"="dotted","Thatcher.Extrapolation"="solid","Weibull.Extrapolation"="dashed","Gompertz.Extrapolation"="dotted"),guide="none") +
scale_color_manual(values=c("Thatcher"="black","Weibull"="black","Gompertz"="black")) +
guides(color=guide_legend(override.aes=list(linetype=c("solid","dashed","dotted")))) +
labs(x="age",y="log death rate",colour=NULL,linetype=NULL) +
theme_bw(base_size = 12) +
theme(axis.text=element_text(size=12),legend.text=element_text(size=12),panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),panel.border=element_blank(),axis.line=element_line(color="black"),legend.position="bottom")


