## ----fig5,fig.cap="Parameter estimates (top to bottom panel – LC, RH, APC, M5, M6, M7) from \\pkg{demofit} (solid lines) and \\pkg{StMoMo} (dashed lines) using Australian male data of years 1980-2021 and ages 50-90.",echo=FALSE,results='hide',out.width="90%",fig.show='hold',warning=FALSE,message=FALSE----
M <- AUSM
M <- M[31:72,51:91]
x <- 50:90
f1 <- LCS(x=x,M=M,curve="makeham2",h=30,jumpoff=2)
f2 <- RHS(x=x,M=M,curve="makeham2",h=30,jumpoff=2)
f3 <- APCS(x=x,M=M,curve="makeham2",h=30,jumpoff=2)
f4 <- CBDS(x=x,M=M,curve="makeham2",h=30,jumpoff=2)
f5 <- CBDCS(x=x,M=M,curve="makeham2",h=30,jumpoff=2)
f6 <- CBDQCS(x=x,M=M,curve="makeham2",h=30,jumpoff=2)
E <- as.matrix(read.table("E.txt",header=FALSE))
temp <- demography::demogdata(data=t(M),pop=E,ages=50:90,years=1980:2021,type="mortality",label="test",name="test")
data <- StMoMo::StMoMoData(temp)
logit1 <- fit(lc(link="logit"),data=data,ages.fit=50:90,years.fit=1980:2021)
logit2 <- fit(rh(link="logit", cohortAgeFun="1"),data=data,ages.fit=50:90,years.fit=1980:2021)
logit3 <- fit(apc(link="logit"),data=data,ages.fit=50:90,years.fit=1980:2021)
logit4 <- fit(cbd(link="logit"),data=data,ages.fit=50:90,years.fit=1980:2021)
logit5 <- fit(m6(link="logit"),data=data,ages.fit=50:90,years.fit=1980:2021)
logit6 <- fit(m7(link="logit"),data=data,ages.fit=50:90,years.fit=1980:2021)
layout(matrix(c(
1,2,3,0,
4,5,6,7,
8,9,10,0
),nrow=3,byrow=TRUE))
par(mar=c(4,4,1,1))
plot(50:90,coef(f1)$alpha,type="l",xlab="age",ylab="alpha",ylim=c(-6,-1),bty="n")
lines(50:90,coef(logit1)$ax,lty=2)
plot(50:90,coef(f1)$beta,type="l",xlab="age",ylab="beta",ylim=c(0.01,0.035),bty="n")
lines(50:90,coef(logit1)$bx,lty=2)
plot(1980:2021,coef(f1)$kappa,type="l",xlab="year",ylab="kappa",ylim=c(-25,25),bty="n")
lines(1980:2021,coef(logit1)$kt,lty=2)
plot(50:90,coef(f2)$alpha,type="l",xlab="age",ylab="alpha",ylim=c(-6,-1),bty="n")
lines(50:90,coef(logit2)$ax,lty=2)
plot(50:90,coef(f2)$beta,type="l",xlab="age",ylab="beta",ylim=c(0.005,0.045),bty="n")
lines(50:90,coef(logit2)$bx,lty=2)
plot(1980:2021,coef(f2)$kappa,type="l",xlab="year",ylab="kappa",ylim=c(-20,25),bty="n")
lines(1980:2021,coef(logit2)$kt,lty=2)
